    /** The symbol as text in the Admiralty Symbols font (R.font.admiralty_symbols_regular ...). */
    val character: String get() = String(Character.toChars(codepoint))

    companion object {
        private val byName: Map<String, AdmiraltySymbol> = values().associateBy { it.symbolName }

        /** Finds a symbol by its name, like "heart-filled". Returns null for an unknown name. */
        fun named(name: String): AdmiraltySymbol? = byName[name]
    }
